        />
      </div>
      <SaveViewDialog open={saveOpen} onOpenChange={setSaveOpen} onSave={(label) => {
        const view = saveView(label, state);
        setState(view.state);
        setSaveOpen(false);
        toast("View saved", { id: "customer-view-feedback" });
      }} />
    </section>
  );
}

