.whatiuse-data-recipe__header h3 { margin: 0; font-size: var(--whatiuse-type-ui); font-weight: 620; letter-spacing: -.012em; }

.whatiuse-data-recipe__header p { margin: 0; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); }

.whatiuse-data-recipe__header small { color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-data-recipe > .whatiuse-data-toolbar {
  padding: 8px 12px;
  background: var(--whatiuse-bg-stage);
}

.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-search-field { width: 210px; }

.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-search { background: var(--whatiuse-bg-surface); }

.whatiuse-data-recipe > .whatiuse-data-table { padding: 0 12px 12px; }

.whatiuse-data-recipe > .whatiuse-data-table > .whatiuse-table__container,
.whatiuse-data-recipe > .whatiuse-data-table > .whatiuse-data-table__virtual-viewport { border-radius: 8px; }

.whatiuse-data-recipe__bulk-slot {
  position: absolute;
  z-index: var(--whatiuse-layer-float);
  right: 12px;
  bottom: 64px;
  left: 12px;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.whatiuse-data-recipe__bulk-slot > * { max-width: calc(100% - 16px); pointer-events: auto; }

@container (max-width: 720px) {
.whatiuse-data-recipe > .whatiuse-data-toolbar {
    grid-template-columns: minmax(0, 1fr);
    align-items: stretch;
  }

.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-data-toolbar__start,
.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-data-toolbar__end {
    width: 100%;
    flex-wrap: wrap;
    justify-content: flex-start;
    margin-left: 0;
  }

.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-search-field {
    width: min(100%, 280px);
    flex: 1 1 220px;
  }
}

@media (max-width: 720px) {
.whatiuse-data-recipe__header { align-items: flex-start; }

.whatiuse-data-recipe > .whatiuse-data-toolbar .whatiuse-search-field { width: 100%; }

.whatiuse-data-recipe > .whatiuse-data-table { padding-inline: 8px; }
}
}
